    const pages = Math.max(1, Math.ceil(shown / size));
    if (ui.page > pages) ui.page = pages;
    if (ui.page < 1) ui.page = 1;
    pageItems = matching.slice((ui.page - 1) * size, (ui.page - 1) * size + size);
