.filters .clear { border:none; background:none; color:var(--accent); text-decoration:underline; cursor:pointer; font-size:12px; }
.filters .saveview { border:1px solid #d3e0fb; background:#eaf1ff; color:var(--accent); border-radius:999px; padding:3px 10px; font-size:12px; cursor:pointer; }

.controls { display:flex; flex-wrap:wrap; gap:12px; align-items:center; justify-content:space-between; margin-bottom:16px; }
.controls-right { display:flex; flex-wrap:wrap; gap:8px; align-items:center; }
.segment { display:inline-flex; border:1px solid var(--line); border-radius:10px; overflow:hidden; background:var(--card); }
.segment button { border:none; background:none; padding:9px 15px; font-size:14px; font-weight:600; color:var(--muted); cursor:pointer; }
.segment button.active { background:var(--accent); color:#fff; }
.sort { font-size:13px; color:var(--muted); display:inline-flex; gap:6px; align-items:center; }
.sort select, .field select { font:inherit; padding:8px 10px; border:1px solid var(--line); border-radius:8px; background:var(--card); color:var(--ink); }

.menu { position:relative; }
.menu-list { position:absolute; right:0; top:100%; margin-top:4px; background:var(--card); border:1px solid var(--line); border-radius:10px; box-shadow:0 8px 24px rgba(16,24,40,.12); min-width:180px; padding:4px; z-index:30; }
.menu-list[hidden] { display:none; }
.menu-list button { display:block; width:100%; text-align:left; border:none; background:none; padding:8px 10px; font-size:13px; border-radius:6px; cursor:pointer; color:var(--ink); }
.menu-list button:hover { background:#f1f5fb; }
.menu-list button.danger { color:var(--danger); }
.menu-empty { padding:8px 10px; font-size:12px; color:var(--muted); max-width:230px; }
.view-row { display:flex; align-items:center; }
