.view-row .apply:hover { background:#f1f5fb; }
.view-row .del { border:none; background:none; color:var(--danger); cursor:pointer; padding:4px 8px; }

.section-title { font-size:13px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); margin:0 0 12px; font-weight:700; }
.count { text-transform:none; letter-spacing:0; font-weight:400; color:#9aa3b2; margin-left:6px; }
.placeholder { text-align:center; color:var(--muted); padding:40px 20px; border:1px dashed var(--line); border-radius:var(--radius); background:#fafbfc; }

.list { display:flex; flex-direction:column; gap:12px; }
