@keyframes flash { 0%{box-shadow:0 0 0 3px rgba(47,109,246,0)} 20%{box-shadow:0 0 0 3px rgba(47,109,246,.5)} 100%{box-shadow:0 0 0 3px rgba(47,109,246,0)} }
.selwrap { display:none; padding-top:2px; }
